 12616  /**
 12617   * xmlCtxtParseInternalEntity:
 12618   * @oldctxt:  the existing parsing context
 12619   * @string:  the input string in UTF8 or ISO-Latin (zero terminated)
 12620   * @user_data:  the user data field for the parser context
 12621   * @lst:  the return value for the set of parsed nodes
 12622   *
 12623   *
 12624   * Parse a well-balanced chunk of an XML document
 12625   * called by the parser
 12626   * The allowed sequence for the Well Balanced Chunk is the one defined by
 12627   * the content production in the XML grammar:
 12628   *
 12629   * [43] content ::= (element | CharData | Reference | CDSect | PI | Comment)*
 12630   *
 12631   * Returns XML_ERR_OK if the chunk is well balanced, and the parser
 12632   * error code otherwise
 12633   *
 12634   * In case recover is set to 1, the nodelist will not be empty even if
 12635   * the parsed chunk is not well balanced.
 12636   */
 12637  static xmlParserErrors
 12638  xmlCtxtParseInternalEntity(xmlParserCtxtPtr ctxt, const xmlChar *string,
 12639                             xmlNodePtr *list) {
 12640      xmlParserInputPtr input;
 12641      xmlNodePtr root;
 12642      unsigned long consumed;
 12643
 12644      if (list != NULL)
 12645          *list = NULL;
 12646
 12647      if ((ctxt == NULL) || (string == NULL))
 12648          return(XML_ERR_ARGUMENT);
 12649
 12650      input = xmlNewStringInputStream(ctxt, string);
 12651      if (input == NULL)
 12652          return(ctxt->errNo);
 12653
 12654      root = xmlCtxtParseContent(ctxt, input, 0 /* hasTextDecl */);
 12655
 12656      if ((list != NULL) && (root != NULL)) {
 12657          xmlNodePtr cur;
 12658
 12659          /*
 12660           * Return the newly created nodeset after unlinking it from
 12661           * their pseudo parent.
 12662           */
 12663          cur = root->children;
 12664          *list = cur;
 12665          while (cur != NULL) {
 12666              cur->parent = NULL;
 12667              cur = cur->next;
 12668          }
 12669          root->children = NULL;
 12670          root->last = NULL;
 12671      }
 12672
 12673      /*
 12674       * Also record the size of the entity parsed
 12675       */
 12676      consumed = input->consumed;
 12677      xmlSaturatedAddSizeT(&consumed, input->cur - input->base);
 12678
 12679      xmlSaturatedAdd(&ctxt->sizeentcopy, consumed);
 12680
 12681      xmlFreeNode(root);
 12682      xmlFreeInputStream(input);
 12683
 12684      return(ctxt->errNo);
 12685  }
