 12687  /**
 12688   * xmlParseInNodeContext:
 12689   * @node:  the context node
 12690   * @data:  the input string
 12691   * @datalen:  the input string length in bytes
 12692   * @options:  a combination of xmlParserOption
 12693   * @lst:  the return value for the set of parsed nodes
 12694   *
 12695   * Parse a well-balanced chunk of an XML document
 12696   * within the context (DTD, namespaces, etc ...) of the given node.
 12697   *
 12698   * The allowed sequence for the data is a Well Balanced Chunk defined by
 12699   * the content production in the XML grammar:
 12700   *
 12701   * [43] content ::= (element | CharData | Reference | CDSect | PI | Comment)*
 12702   *
 12703   * Returns XML_ERR_OK if the chunk is well balanced, and the parser
 12704   * error code otherwise
 12705   */
 12706  xmlParserErrors
 12707  xmlParseInNodeContext(xmlNodePtr node, const char *data, int datalen,
 12708                        int options, xmlNodePtr *lst) {
 12709      xmlParserCtxtPtr ctxt;
 12710      xmlDocPtr doc = NULL;
 12711      xmlNodePtr fake, cur;
 12712      int nsnr = 0;
 12713
 12714      xmlParserErrors ret = XML_ERR_OK;
 12715
 12716      /*
 12717       * check all input parameters, grab the document
 12718       */
 12719      if ((lst == NULL) || (node == NULL) || (data == NULL) || (datalen < 0))
 12720          return(XML_ERR_INTERNAL_ERROR);
 12721      switch (node->type) {
 12722          case XML_ELEMENT_NODE:
 12723          case XML_ATTRIBUTE_NODE:
 12724          case XML_TEXT_NODE:
 12725          case XML_CDATA_SECTION_NODE:
 12726          case XML_ENTITY_REF_NODE:
 12727          case XML_PI_NODE:
 12728          case XML_COMMENT_NODE:
 12729          case XML_DOCUMENT_NODE:
 12730          case XML_HTML_DOCUMENT_NODE:
 12731              break;
 12732          default:
 12733              return(XML_ERR_INTERNAL_ERROR);
 12734
 12735      }
 12736      while ((node != NULL) && (node->type != XML_ELEMENT_NODE) &&
 12737             (node->type != XML_DOCUMENT_NODE) &&
 12738             (node->type != XML_HTML_DOCUMENT_NODE))
 12739          node = node->parent;
 12740      if (node == NULL)
 12741          return(XML_ERR_INTERNAL_ERROR);
 12742      if (node->type == XML_ELEMENT_NODE)
 12743          doc = node->doc;
 12744      else
 12745          doc = (xmlDocPtr) node;
 12746      if (doc == NULL)
 12747          return(XML_ERR_INTERNAL_ERROR);
 12748
 12749      /*
 12750       * allocate a context and set-up everything not related to the
 12751       * node position in the tree
 12752       */
 12753      if (doc->type == XML_DOCUMENT_NODE)
 12754          ctxt = xmlCreateMemoryParserCtxt((char *) data, datalen);
 12755  #ifdef LIBXML_HTML_ENABLED
 12756      else if (doc->type == XML_HTML_DOCUMENT_NODE) {
 12757          ctxt = htmlCreateMemoryParserCtxt((char *) data, datalen);
 12758          /*
 12759           * When parsing in context, it makes no sense to add implied
 12760           * elements like html/body/etc...
 12761           */
 12762          options |= HTML_PARSE_NOIMPLIED;
 12763      }
 12764  #endif
 12765      else
 12766          return(XML_ERR_INTERNAL_ERROR);
 12767
 12768      if (ctxt == NULL)
 12769          return(XML_ERR_NO_MEMORY);
 12770
 12771      /*
 12772       * Use input doc's dict if present, else assure XML_PARSE_NODICT is set.
 12773       * We need a dictionary for xmlDetectSAX2, so if there's no doc dict
 12774       * we must wait until the last moment to free the original one.
 12775       */
 12776      if (doc->dict != NULL) {
 12777          if (ctxt->dict != NULL)
 12778              xmlDictFree(ctxt->dict);
 12779          ctxt->dict = doc->dict;
 12780      } else
 12781          options |= XML_PARSE_NODICT;
 12782
 12783      if (doc->encoding != NULL)
 12784          xmlSwitchEncodingName(ctxt, (const char *) doc->encoding);
 12785
 12786      xmlCtxtUseOptionsInternal(ctxt, options, NULL);
 12787      xmlDetectSAX2(ctxt);
 12788      ctxt->myDoc = doc;
 12789      /* parsing in context, i.e. as within existing content */
 12790      ctxt->input_id = 2;
 12791      ctxt->instate = XML_PARSER_CONTENT;
 12792
 12793      fake = xmlNewDocComment(node->doc, NULL);
 12794      if (fake == NULL) {
 12795          xmlFreeParserCtxt(ctxt);
 12796          return(XML_ERR_NO_MEMORY);
 12797      }
 12798      xmlAddChild(node, fake);
 12799
 12800      if (node->type == XML_ELEMENT_NODE) {
 12801          nodePush(ctxt, node);
 12802          /*
 12803           * initialize the SAX2 namespaces stack
 12804           */
 12805          cur = node;
 12806          while ((cur != NULL) && (cur->type == XML_ELEMENT_NODE)) {
 12807              xmlNsPtr ns = cur->nsDef;
 12808              xmlHashedString hprefix, huri;
 12809
 12810              while (ns != NULL) {
 12811                  hprefix = xmlDictLookupHashed(ctxt->dict, ns->prefix, -1);
 12812                  huri = xmlDictLookupHashed(ctxt->dict, ns->href, -1);
 12813                  if (xmlParserNsPush(ctxt, &hprefix, &huri, ns, 1) > 0)
 12814                      nsnr++;
 12815                  ns = ns->next;
 12816              }
 12817              cur = cur->parent;
 12818          }
 12819      }
 12820
 12821      if ((ctxt->validate) || (ctxt->replaceEntities != 0)) {
 12822          /*
 12823           * ID/IDREF registration will be done in xmlValidateElement below
 12824           */
 12825          ctxt->loadsubset |= XML_SKIP_IDS;
 12826      }
 12827
 12828  #ifdef LIBXML_HTML_ENABLED
 12829      if (doc->type == XML_HTML_DOCUMENT_NODE)
 12830          __htmlParseContent(ctxt);
 12831      else
 12832  #endif
 12833          xmlParseContent(ctxt);
 12834
 12835      xmlParserNsPop(ctxt, nsnr);
 12836      if ((RAW == '<') && (NXT(1) == '/')) {
 12837          xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
 12838      } else if (RAW != 0) {
 12839          xmlFatalErr(ctxt, XML_ERR_EXTRA_CONTENT, NULL);
 12840      }
 12841      if ((ctxt->node != NULL) && (ctxt->node != node)) {
 12842          xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
 12843          ctxt->wellFormed = 0;
 12844      }
 12845
 12846      if ((ctxt->wellFormed) ||
 12847          ((ctxt->recovery) && (ctxt->errNo != XML_ERR_NO_MEMORY))) {
 12848          ret = XML_ERR_OK;
 12849      } else {
 12850          ret = (xmlParserErrors) ctxt->errNo;
 12851      }
 12852
 12853      /*
 12854       * Return the newly created nodeset after unlinking it from
 12855       * the pseudo sibling.
 12856       */
 12857
 12858      cur = fake->next;
 12859      fake->next = NULL;
 12860      node->last = fake;
 12861
 12862      if (cur != NULL) {
 12863          cur->prev = NULL;
 12864      }
 12865
 12866      *lst = cur;
 12867
 12868      while (cur != NULL) {
 12869          cur->parent = NULL;
 12870          cur = cur->next;
 12871      }
 12872
 12873      xmlUnlinkNode(fake);
 12874      xmlFreeNode(fake);
 12875
 12876
 12877      if (ret != XML_ERR_OK) {
 12878          xmlFreeNodeList(*lst);
 12879          *lst = NULL;
 12880      }
 12881
 12882      if (doc->dict != NULL)
 12883          ctxt->dict = NULL;
 12884      xmlFreeParserCtxt(ctxt);
 12885
 12886      return(ret);
 12887  }
